import pandas as pd
import numpy as np

# Define indicators
def bollinger_bands(price, window, std_dev):
    rolling_mean = price.rolling(window).mean()
    rolling_std = price.rolling(window).std()
    upper_band = rolling_mean + (rolling_std * std_dev)
    lower_band = rolling_mean - (rolling_std * std_dev)
    return upper_band, lower_band

def money_flow_index(high, low, close, volume, window):
    typical_price = (high + low + close) / 3
    money_flow = typical_price * volume
    positive_flow = []
    negative_flow = []
    for i in range(len(money_flow)):
        if money_flow[i] > 0:
            positive_flow.append(money_flow[i])
            negative_flow.append(0)
        else:
            positive_flow.append(0)
            negative_flow.append(abs(money_flow[i]))
    positive_mfi = np.array(positive_flow).rolling(window).sum()
    negative_mfi = np.array(negative_flow).rolling(window).sum()
    mfi = 100 - (100 / (1 + (positive_mfi / negative_mfi)))
    return mfi

def rsi(price, window):
    delta = price.diff(1)
    up_days = delta.copy()
    up_days[delta <= 0] = 0
    down_days = delta.copy()
    down_days[delta > 0] = 0
    roll_up1 = up_days.rolling(window).mean()
    roll_down1 = down_days.rolling(window).mean().abs()
    RS = roll_up1 / roll_down1
    RSI = 100.0 - (100.0 / (1.0 + RS))
    return RSI

def parabolic_sar(high, low, acceleration, maximum):
    sar = low.iloc[0]
    direction = 1
    for i in range(1, len(high)):
        if direction == 1:
            sar = min(sar, low.iloc[i])
            if high.iloc[i] > high.iloc[i-1]:
                sar = sar + (acceleration * (high.iloc[i] - sar))
            else:
                sar = sar + (acceleration * (low.iloc[i] - sar))
            if sar > high.iloc[i]:
                direction = -1
        else:
            sar = max(sar, high.iloc[i])
            if low.iloc[i] < low.iloc[i-1]:
                sar = sar - (acceleration * (sar - low.iloc[i]))
            else:
                sar = sar - (acceleration * (high.iloc[i] - sar))
            if sar < low.iloc[i]:
                direction = 1
    return sar

# Define strategy
