    upper_band, lower_band = bollinger_bands(price, 20, 2)
    mfi = money_flow_index(high, low, close, volume, 14)
    rsi = rsi(price, 14)
    sar = parabolic_sar(high, low, 0.02, 0.2)

    long_entry = (price < lower_band) & (mfi < 20) & (rsi < 30) & (sar < price)
    short_entry = (price > upper_band) & (mfi > 80) & (rsi > 70) & (sar > price)

    long_exit = (price > upper_band) & (mfi > 80) & (rsi > 70) & (sar > price)
    short_exit = (price < lower_band) & (mfi < 20) & (rsi < 30) & (sar < price)

